+      .error-text {
+        margin: 0.35rem 0 0;
+        font-size: 0.9375rem;
+        line-height: 1.45;
+      }
+
+      .help-text {
+        color: var(--muted);
+      }
+
+      .error-text {
+        color: var(--danger);
+      }
+
