<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Terms of Use Consent</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f3f7fb;
        --surface: rgba(255, 255, 255, 0.9);
        --surface-strong: #ffffff;
        --text: #102033;
        --muted: #5d6b7d;
        --border: #d7e0ea;
        --accent: #2563eb;
        --accent-strong: #1d4ed8;
        --danger: #b42318;
        --shadow: 0 24px 60px rgba(16, 32, 51, 0.12);
      }

      * {
        box-sizing: border-box;
      }

      html,
      body {
        margin: 0;
        min-height: 100%;
      }

      body {
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top, rgba(37, 99, 235, 0.14), transparent 36%),
          linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
      }

      a {
        color: var(--accent-strong);
      }

      a:focus-visible,
      button:focus-visible,
      input:focus-visible {
        outline: 3px solid #111827;
        outline-offset: 3px;
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        padding: 0.75rem 1rem;
        border-radius: 999px;
        background: var(--surface-strong);
        color: var(--text);
        transform: translateY(-200%);
        transition: transform 160ms ease;
        box-shadow: var(--shadow);
        z-index: 10;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .page {
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 2rem 1rem;
      }

      .card {
        width: min(100%, 34rem);
        padding: 2rem;
        border: 1px solid rgba(215, 224, 234, 0.85);
        border-radius: 24px;
        background: var(--surface);
        box-shadow: var(--shadow);
        backdrop-filter: blur(14px);
      }

      .eyebrow {
        margin: 0 0 0.5rem;
        font-size: 0.875rem;
        font-weight: 600;
        letter-spacing: 0.04em;
        text-transform: uppercase;
        color: var(--accent-strong);
      }

      h1 {
        margin: 0;
        font-size: clamp(1.75rem, 4vw, 2.4rem);
        line-height: 1.1;
      }

      .subtitle {
        margin: 0.75rem 0 0;
        color: var(--muted);
        line-height: 1.5;
      }

      form {
        margin-top: 1.75rem;
      }

      .form-field {
        padding: 1rem 1rem 1rem 0.25rem;
        border: 1px solid var(--border);
        border-radius: 18px;
        background: var(--surface-strong);
      }

      .checkbox-row {
        display: grid;
        grid-template-columns: 1.25rem 1fr;
        gap: 0.85rem;
        align-items: start;
      }

      .checkbox-row input {
        margin-top: 0.2rem;
        width: 1.125rem;
        height: 1.125rem;
        accent-color: var(--accent);
      }

      .checkbox-label {
        display: inline-flex;
        gap: 0.25rem;
        align-items: center;
        font-weight: 600;
        cursor: pointer;
      }

      .required-mark {
        color: var(--danger);
      }

      .help-text,
      .error-text {
        margin: 0.35rem 0 0;
        font-size: 0.9375rem;
        line-height: 1.45;
      }

      .help-text {
        color: var(--muted);
      }

      .error-text {
        color: var(--danger);
      }

      .actions {
        margin-top: 1.25rem;
        display: flex;
        gap: 0.75rem;
        align-items: center;
        justify-content: flex-end;
      }

      .button {
        border: 0;
        border-radius: 999px;
        padding: 0.875rem 1.25rem;
        font: inherit;
        font-weight: 600;
        color: #fff;
        background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
        box-shadow: 0 14px 30px rgba(37, 99, 235, 0.24);
        cursor: pointer;
      }

      .button:hover {
        filter: brightness(1.03);
      }

      .status {
        min-height: 1.25rem;
        margin-top: 1rem;
        color: var(--accent-strong);
        font-weight: 600;
      }

      @media (max-width: 480px) {
        .card {
          padding: 1.25rem;
          border-radius: 20px;
        }

        .actions {
          justify-content: stretch;
        }

        .button {
          width: 100%;
        }
      }

      @media (forced-colors: active) {
        .card,
        .form-field {
          border: 1px solid CanvasText;
        }

        .button {
          border: 1px solid ButtonText;
          background: ButtonFace;
          color: ButtonText;
          box-shadow: none;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="root"></div>

    <script>
      function ConsentField() {
        return `
          <div class="form-field">
            <div class="checkbox-row">
              <input
                id="agree-terms"
                name="agreeTerms"
                type="checkbox"
                required
                aria-describedby="agree-help"
              />
              <div>
                <label class="checkbox-label" for="agree-terms">
                  I agree to the Terms of Use <span class="required-mark" aria-hidden="true">*</span>
                </label>
                <p id="agree-help" class="help-text">Required to continue.</p>
                <p id="agree-error" class="error-text" hidden>Error: You must agree to the Terms of Use to continue.</p>
              </div>
            </div>
          </div>
        `;
      }

      function ConsentForm() {
        return `
          <main id="main-content" class="page">
            <section class="card" aria-labelledby="page-title">
              <p class="eyebrow">Account access</p>
              <h1 id="page-title">Review and accept the terms</h1>
              <p class="subtitle">Please confirm your agreement before continuing.</p>

              <form id="consent-form" novalidate>
                ${ConsentField()}
                <div class="actions">
                  <button class="button" type="submit">Agree and continue</button>
                </div>
                <p class="status" id="form-status" aria-live="polite"></p>
              </form>
            </section>
          </main>
        `;
      }

      function App() {
        return ConsentForm();
      }

      document.getElementById("root").innerHTML = App();

      const form = document.getElementById("consent-form");
      const checkbox = document.getElementById("agree-terms");
      const error = document.getElementById("agree-error");
      const status = document.getElementById("form-status");

      function setErrorState(isInvalid) {
        checkbox.setAttribute("aria-invalid", isInvalid ? "true" : "false");
        error.hidden = !isInvalid;
        checkbox.setAttribute("aria-describedby", isInvalid ? "agree-help agree-error" : "agree-help");
      }

      form.addEventListener("submit", function (event) {
        event.preventDefault();

        if (!checkbox.checked) {
          setErrorState(true);
          status.textContent = "";
          checkbox.focus();
          return;
        }

        setErrorState(false);
        status.textContent = "Thanks — your consent has been recorded.";
      });

      checkbox.addEventListener("change", function () {
        if (checkbox.checked) {
          setErrorState(false);
          status.textContent = "";
        }
      });
    </script>
  </body>
</html>
