         display: grid;
         place-items: center;
         padding: 2rem 1rem;
       }

       .card {
         width: min(100%, 34rem);
         padding: 2rem;
         border: 1px solid rgba(215, 224, 234, 0.85);
         border-radius: 24px;
         background: var(--surface);
         box-shadow: var(--shadow);
         backdrop-filter: blur(14px);
       }

       .eyebrow {
         margin: 0 0 0.5rem;
         font-size: 0.875rem;
         font-weight: 600;
         letter-spacing: 0.04em;
         text-transform: uppercase;
         color: var(--accent-strong);
       }

       h1 {
         margin: 0;
         font-size: clamp(1.75rem, 4vw, 2.4rem);
         line-height: 1.1;
       }

       .subtitle {
         margin: 0.75rem 0 0;
         color: var(--muted);
         line-height: 1.5;
       }

       form {
         margin-top: 1.75rem;
       }

       .form-field {
         padding: 1rem 1rem 1rem 0.25rem;
         border: 1px solid var(--border);
         border-radius: 18px;
         background: var(--surface-strong);
       }

       .checkbox-row {
         display: grid;
         grid-template-columns: 1.25rem 1fr;
         gap: 0.85rem;
         align-items: start;
       }

       .checkbox-row input {
         margin-top: 0.2rem;
         width: 1.125rem;
         height: 1.125rem;
         accent-color: var(--accent);
       }

       .checkbox-label {
         display: inline-flex;
         gap: 0.25rem;
         align-items: center;
         font-weight: 600;
         cursor: pointer;
       }

       .required-mark {
         color: var(--danger);
       }

       .help-text,
       .error-text {
         margin: 0.35rem 0 0;
         font-size: 0.9375rem;
         line-height: 1.45;
       }

       .help-text {
         color: var(--muted);
       }

       .error-text {
         color: var(--danger);
       }

       .actions {
         margin-top: 1.25rem;
         display: flex;
         gap: 0.75rem;
         align-items: center;
         justify-content: flex-end;
